function clearRecallAttemptUI(){recallTranscriptText='';$('#recallResult').classList.add('hidden');$('#recallCompare').classList.add('hidden');$('#recallTranscript').textContent='';$('#vocabRecall').innerHTML='';$('#grammarFixes').innerHTML='';$('#grammarCheckText').textContent='Waiting for this attempt…';$('#recallStart').classList.remove('hidden');$('#recallStart').disabled=false;$('#recallStop').disabled=true;$('#recallLive').textContent=`Ready for Recall ${recallAttemptNo}. Press Record when you are ready.`;$('#recallBadge').textContent=`RECALL ${recallAttemptNo} · TEXT HIDDEN`;recallSeconds=0;updateFloatingRecorder(true)}
function retryRecall(autoStart=false){recallAnalysisSeq++;recallActiveAnalysis=recallAnalysisSeq;const prev=recallScores[0]?.attempts||[];const maxNo=prev.length?Math.max(...prev.map(x=>Number(x.no)||0)):0;recallAttemptNo=maxNo+1;clearRecallAttemptUI();if(autoStart)setTimeout(startRecallRecognition,100)}
function targetMatchScore(text,variants){const heard=norm(text).split(' ').filter(Boolean);let best=0;for(const variant of variants){const v=norm(variant).split(' ').filter(Boolean);if(!v.length)continue;const exact=(' '+heard.join(' ')+' ').includes(' '+v.join(' ')+' ');if(exact){best=1;continue}const matched=v.filter(w=>heard.includes(w)).length;let overlap=matched/v.length;if(v.length>=3){for(let i=0;i<=heard.length-v.length+1;i++){const window=heard.slice(i,i+v.length+1);const local=v.filter(w=>window.includes(w)).length/v.length;overlap=Math.max(overlap,local)}}best=Math.max(best,overlap)}return best}
function renderAttemptHistory(attempts,currentNo,best){const el=$('#recallAttemptHistory');if(!el)return;el.innerHTML=attempts.map(a=>`<span class="attempt-chip ${a.no===currentNo?'current':''} ${a.overall===best?'best':''}">Recall ${a.no} · ${clampMetric(a.overall)}%</span>`).join('')}
function renderRecallMetric(scoreEl,statusEl,noteEl,score,note,good=85,ok=70){score=clampMetric(score);$(scoreEl).textContent=score+'%';const st=metricState(score,good,ok),p=$(statusEl);p.textContent=st.label;p.className='metric-status '+st.cls;$(noteEl).textContent=note}
function renderLanguageNotes(lang){const gP=$('#grammarSummaryPill'),nP=$('#naturalSummaryPill'),fix=$('#grammarFixes');gP.className='lang-pill '+(lang.grammarIssues.length?'bad':'good');gP.textContent=lang.grammarIssues.length?`Grammar: ${lang.grammarIssues.length} issue${lang.grammarIssues.length===1?'':'s'} found`:'Grammar: no confident issue detected';nP.className='lang-pill '+(lang.naturalIssues.length?'warn':'good');nP.textContent=lang.naturalIssues.length?`Wording: ${lang.naturalIssues.length} phrase to check`:'Wording: no flagged phrase';const notes=[];for(const x of lang.grammarIssues)notes.push(`<div class="fix-line bad"><b>Grammar:</b> ${escapeHtml(x.match)} → <b>${escapeHtml(x.suggestion)}</b><span class="fix-rule">${escapeHtml(x.rule)}</span></div>`);for(const x of lang.naturalIssues)notes.push(`<div class="fix-line"><b>Wording:</b> ${escapeHtml(x.match)} → <b>${escapeHtml(x.suggestion)}</b><span class="fix-rule">${escapeHtml(x.rule||'common collocation / wording pattern')}</span></div>`);if(lang.gecRejected)notes.push(`<div class="fix-line"><b>Safety:</b> A broad model rewrite was ignored.<span class="fix-rule">ShadowLab only accepts small corrections that preserve your original meaning.</span></div>`);fix.innerHTML=notes.join('');if(lang.grammarIssues.length)$('#grammarCheckText').textContent='Grammar needs attention. Only specific rule matches or meaning-preserving minimal edits are shown below.';else if(lang.naturalIssues.length)$('#grammarCheckText').textContent='No confident grammar problem was found, but one wording/collocation pattern may sound unnatural.';else $('#grammarCheckText').textContent=lang.gecAvailable===false?'No issue was found by the expanded grammar-rule engine. The deeper local grammar model was unavailable on this device.':'No issue was found by the expanded grammar rules or the constrained local grammar model.'}
async function finishRecall(attemptNo=recallAttemptNo,transcript=recallTranscriptText,analysisToken=++recallAnalysisSeq){const heard=norm(transcript),mem=questions[0].memory;if(!heard){$('#recallLive').textContent='No speech was recognized. Try again.';$('#recallStart').disabled=false;return}recallActiveAnalysis=analysisToken;$('#recallLive').textContent=`Checking Recall ${attemptNo}: meaning, target chunks and language…`;const words=new Set(heard.split(' ')),hits=mem.content.filter(w=>words.has(norm(w))).length,lexicalMeaning=mem.content.length?Math.round(hits/mem.content.length*100):100,targetHits=mem.targets.map(t=>{const strength=targetMatchScore(heard,t.variants);return {label:t.label,hit:strength>=.72,strength}}),target=targetHits.length?Math.round(targetHits.reduce((n,x)=>n+x.strength,0)/targetHits.length*100):100,missing=targetHits.filter(x=>!x.hit).map(x=>x.label),lang=await analyzeRecallLanguage(transcript);if(analysisToken!==recallActiveAnalysis)return;const semantic=lang.semanticScore,meaning=clampMetric(semantic==null?lexicalMeaning:semantic*.82+lexicalMeaning*.18,lexicalMeaning),grammar=clampMetric(lang.grammar,90),natural=clampMetric(lang.natural,90),overall=clampMetric(meaning*.35+target*.30+grammar*.20+natural*.15),prev=recallScores[0]?.attempts||[],entry={no:attemptNo,content:meaning,vocab:target,grammar,natural,overall,transcript,missing,grammarIssues:lang.grammarIssues,naturalIssues:lang.naturalIssues,semanticSimilarity:lang.similarity},attempts=[...prev.filter(x=>Number(x.no)!==Number(attemptNo)),entry].sort((a,b)=>a.no-b.no),best=Math.max(...attempts.map(x=>clampMetric(x.overall)));recallTranscriptText=transcript;recallScores[0]={content:meaning,vocab:target,grammar,natural,overall,best,transcript,attempts,reviewed:recallReviewed};renderRecallMetric('#recallContentScore','#meaningStatus','#meaningNote',meaning,semantic==null?`Main idea estimated from key content: ${lexicalMeaning}%.`:`Semantic match + key content. Main idea retained: ${meaning}%.`);const hitCount=targetHits.filter(x=>x.hit).length;renderRecallMetric('#recallVocabScore','#targetStatus','#targetNote',target,`${hitCount}/${targetHits.length} required target chunk${targetHits.length===1?'':'s'} retrieved. This answer requires ${targetHits.length} because target count varies with answer length and language density.`,80,60);renderRecallMetric('#recallGrammarScore','#grammarStatus','#grammarNote',grammar,lang.grammarIssues.length?`${lang.grammarIssues.length} high-confidence grammar issue${lang.grammarIssues.length===1?'':'s'} found.`:'No high-confidence grammar issue detected.',90,75);renderRecallMetric('#recallNaturalScore','#naturalStatus','#naturalNote',natural,lang.naturalIssues.length?`${lang.naturalIssues.length} common wording/collocation issue${lang.naturalIssues.length===1?'':'s'} flagged.`:'No common collocation problem was flagged.',90,75);$('#recallOverallScore').textContent=overall+'%';$('#recallTranscript').textContent=transcript;$('#recallAttemptLabel').textContent=`Recall ${attemptNo} · this transcript is stored separately from earlier attempts.`;$('#vocabRecall').innerHTML=targetHits.map(x=>`<span class="vchip ${x.hit?'hit':''}">${x.hit?'✓':'○'} ${escapeHtml(x.label)}${x.hit?'':` · ${Math.round(x.strength*100)}% match`}</span>`).join('');renderLanguageNotes(lang);renderAttemptHistory(attempts,attemptNo,best);const previous=attempts.filter(x=>x.no<attemptNo).sort((a,b)=>b.no-a.no)[0];if(previous){$('#recallCompare').classList.remove('hidden');$('#recallCompare').textContent=`Recall ${previous.no}: ${clampMetric(previous.overall)}% → Recall ${attemptNo}: ${overall}% · Target chunks ${clampMetric(previous.vocab)}% → ${target}%`;}else $('#recallCompare').classList.add('hidden');$('#recallResult').classList.remove('hidden');$('#recallStart').classList.add('hidden');$('#recallLive').innerHTML=missing.length?`Recall ${attemptNo} saved. Missing / weak target language: <b>${missing.join(' · ')}</b>. Use Recall again whenever you want another fresh attempt.`:`Recall ${attemptNo} saved. All target chunks were retrieved strongly enough. You can Recall again to improve the language or finish the question.`;$('#reviewRecallBtn').classList.toggle('hidden',recallReviewed||target>=95);saveProgress();updateFloatingRecorder(true)}
function finishRecallStage(){if(!qRecallDone())return toast('Do at least one Recall attempt first.');saveProgress();finishLesson()}

const CLOUD_PROFILE_KEY='shadowlab-cloud-profile-v1',CLOUD_API='/.netlify/functions/shadowlab';
function cloudProfile(){try{return JSON.parse(localStorage.getItem(CLOUD_PROFILE_KEY)||'null')}catch{return null}}
async function cloudApi(action,payload={}){const res=await fetch(CLOUD_API,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,...payload})});let body={};try{body=await res.json()}catch{}if(!res.ok||body.ok===false)throw new Error(body.error||`Cloud error ${res.status}`);return body}
function avgMetric(ds,key){const v=ds.map(x=>Number(x?.[key])).filter(Number.isFinite);return v.length?Math.round(v.reduce((a,b)=>a+b,0)/v.length):null}
function buildCloudSummary(){const vals=Object.values(scores).filter(x=>x&&x.latest!=null),ds=vals.map(x=>x.diagnostics).filter(Boolean);const first=vals.length?Math.round(vals.reduce((a,b)=>a+(b.first??b.latest),0)/vals.length):0,latest=vals.length?Math.round(vals.reduce((a,b)=>a+b.latest,0)/vals.length):0;const allWords=vals.flatMap(x=>x.wordScores||[]).filter(w=>w.score!=null),bad=allWords.filter(w=>w.score<70),under70=allWords.length?Math.round(bad.length/allWords.length*100):0;const r=recallScores[0],recall=r?(r.best??r.overall??r.vocab):0;return {shadowFirst:first,shadowLatest:latest,clarity:avgMetric(ds,'clarity'),fluency:avgMetric(ds,'flu'),rhythm:avgMetric(ds,'rhythm'),connectedSpeech:avgMetric(ds,'connected'),under70Pct:under70,recallScore:recall,attempts:vals.reduce((n,x)=>n+(x.history?.length||1),0),transcript:vals.map((x,i)=>`Sentence ${i+1}: ${x.diagnostics?.heardText||''}`).join('\n'),recallTranscript:r?.transcript||'',detail:{studyTrack:STUDY_TRACK||null,routeAnswer:route.model_answer,targetChunks:route.target_chunks,sentences:vals.map((x,i)=>({sentence:i+1,first:x.first,latest:x.latest,diagnostics:x.diagnostics,history:x.history})),recall:r||null}}}
async function syncQuestionResult(summary){const p=cloudProfile(),box=document.querySelector('#cloudSubmitStatus');if(!p){box.className='sync-status bad';box.querySelector('span').textContent='No student profile found. Return to the homepage and enter your name and class.';return}box.className='sync-status wait';box.querySelector('span').textContent='Sending result to teacher dashboard…';try{await cloudApi('submit_result',{studentId:p.id,studentKey:p.studentKey,submission:{questionId:item.id,questionText:effectiveQuestion,topic:item.topic,routeId:route.route_id,routeLabel:route.label,...summary}});box.className='sync-status ok';box.querySelector('span').textContent='Submitted · Waiting for teacher review';}catch(e){console.error(e);box.className='sync-status bad';box.querySelector('span').textContent='Could not sync right now. Your local result is safe; reopen this question and finish again after the connection is restored.'}}
function saveProgress(){localStorage.setItem(stateKey(),JSON.stringify({idx,attempt,scores,recallScores,completed:[...completed],listenCounts}));localStorage.setItem('shadowlab-last-url-v1',`practice.html?q=${item.id}&r=${route.route_id}${STUDY_TRACK?`&track=${STUDY_TRACK}`:''}`);localStorage.setItem('shadowlab-last-topic-v1',item.topic)}
function restoreProgress(){try{const p=JSON.parse(localStorage.getItem(stateKey())||'null');if(!p)return;idx=Math.min(p.idx||0,lesson.length-1);attempt=p.attempt||0;scores=p.scores||{};recallScores=p.recallScores||{};completed=new Set(p.completed||[]);listenCounts=p.listenCounts||{}}catch(e){}}
function markComplete(){const vals=Object.values(scores).filter(x=>x&&x.latest!=null),first=vals.length?Math.round(vals.reduce((a,b)=>a+b.first,0)/vals.length):0,latest=vals.length?Math.round(vals.reduce((a,b)=>a+b.latest,0)/vals.length):0,r=recallScores[0],recall=r?(r.best??r.overall??r.vocab):0;let all={};try{all=JSON.parse(localStorage.getItem('shadowlab-completed-v1')||'{}')}catch{}all[item.id]={route:route.route_id,latest,first,recall,at:Date.now(),status:'pending'};localStorage.setItem('shadowlab-completed-v1',JSON.stringify(all));return {first,latest,recall}}
function finishLesson(){const x=markComplete(),cloud=buildCloudSummary();$('#finalScore').textContent=x.latest||'—';$('#beforeScore').textContent=x.first||'—';$('#finalRecallScore').textContent=x.recall?x.recall+'%':'—';show('resultView');syncQuestionResult(cloud)}
function init(){const cp=cloudProfile();if(!cp){location.replace(`index.html?profile=1&return=${encodeURIComponent(location.href)}`);return}document.querySelector('#practiceStudentName').textContent=cp.fullName;document.querySelector('#practiceStudentClass').textContent=cp.className;document.title=`${item.topic} · IELTS SHADOWLAB`;$('#topicEyebrow').textContent=item.topic;$('#practiceQuestion').textContent=effectiveQuestion;$('#routePill').textContent=`Route ${route.route_id} · ${route.label}`;$('#sideRoute').textContent=`${route.route_id} — ${route.label}${STUDY_TRACK?` · ${STUDY_TRACK.replace('_',' ')}`:''}`;$('#sideAnswer').textContent=route.model_answer;restoreProgress();practiceMode='shadow';renderLesson();populateVoiceSelect();updateFloatingRecorder(true)}
$('#playModel').onclick=()=>speak(lesson[idx].text,speed,true);$('#playSlow').onclick=()=>speak(lesson[idx].text,.55,true);$$('.speed button').forEach(b=>b.onclick=()=>{$$('.speed button').forEach(x=>x.classList.remove('on'));b.classList.add('on');speed=+b.dataset.speed});$('#voiceSelect').onchange=e=>{selectedVoiceURI=e.target.value;const v=bestEnglishVoice();toast(v?`Voice: ${v.name}`:'Using browser default English voice')};$('#recordBtn').onclick=startRecording;$('#stopBtn').onclick=stopRecording;$('#floatRecordBtn').onclick=()=>{if(practiceMode!=='recall')return startRecording();if(!$('#recallResult').classList.contains('hidden'))return retryRecall(true);startRecallRecognition()};$('#floatStopBtn').onclick=()=>practiceMode==='recall'?stopRecallRecognition():stopRecording();$('#mockAnalyze').onclick=()=>{if($('#mockAnalyze').classList.contains('locked'))return nudgeRecord();analyze()};$('#startRecallBtn').onclick=()=>{if($('#startRecallBtn').classList.contains('locked'))return nudgePronunciation();openRecall()};$('#recallStart').onclick=startRecallRecognition;$('#recallStop').onclick=stopRecallRecognition;$('#recallAgain').onclick=()=>retryRecall(false);$('#reviewRecallBtn').onclick=reviewRecallOnce;$('#finishRecallBtn').onclick=finishRecallStage;$('#backToShadowBtn').onclick=backToShadow;$('#prevSentence').onclick=()=>{if(idx>0){idx--;attempt=0;renderLesson()}};$('#nextSentence').onclick=()=>{if((listenCounts[idx]||0)<2)return nudgeListen();if(!scores[idx])return nudgeRecord();if(!pronunciationGate().pass)return nudgePronunciation();completed.add(idx);if(!isLastSentence()){saveProgress();idx++;attempt=0;renderLesson();window.scrollTo({top:0,behavior:'smooth'});return}saveProgress();openRecall()};$('#homeBtn').onclick=()=>location.href=backUrl();$('#changeRouteBtn').onclick=$('#changeRouteSide').onclick=()=>location.href=`index.html?topic=${encodeURIComponent(item.topic)}#topics`;$('#backTopicBtn').onclick=()=>location.href=backUrl();$('#practiceAgainBtn').onclick=()=>{localStorage.removeItem(stateKey());location.reload()};$('#nextQuestionBtn').onclick=()=>{const topicItems=DATA.items.filter(x=>x.topic===item.topic);const i=topicItems.findIndex(x=>x.id===item.id),next=topicItems[(i+1)%topicItems.length];location.href=`index.html?topic=${encodeURIComponent(item.topic)}&question=${next.id}#topics`};init();
